import React from "react";
import { Link } from "react-router-dom"; // This is the magic part!
import "../styles/Navbar.css"; 

const Navbar = () => {
  return (
    <nav className="navbar">
      <div className="logo">
        {/* Clicking the logo now swaps the view back to Home */}
        <Link to="/" className="nav-logo">🌊 Garbage Detection</Link>
      </div>

      <ul className="nav-links">
        <li>
          {/* Swaps to Home Page */}
          <Link to="/">Home</Link>
        </li>
        <li>
          {/* Swaps to Home Page (where Upload section is) */}
          <Link to="/">Upload</Link>
        </li>
        <li>
          {/* Swaps to About Page */}
          <Link to="/about">About</Link>
        </li>
      </ul>
    </nav>
  );
};

export default Navbar;
